import math

def colwise(X, op):
    out = []
    for col in zip(*X):
        if op == "sum":
            out.append(sum(col))
        elif op == "mean":
            out.append(sum(col) / len(col))
        else:
            out.append(max(col))
    return out

def standardize(X):
    mu = colwise(X, "mean")
    sd = []
    for col, m in zip(zip(*X), mu):
        sd.append(math.sqrt(sum((v - m) ** 2 for v in col) / len(col)))
    return [[round((v - m) / s, 3) for v, m, s in zip(row, mu, sd)] for row in X]

