def step(X, y, w, lr):
    m = len(X)
    p = [sigmoid(sum(a * b for a, b in zip(row, w))) for row in X]
    grad = [sum((p[i] - y[i]) * X[i][j] for i in range(m)) / m for j in range(len(w))]
    return [round(w[j] - lr * grad[j], 4) for j in range(len(w))]

def predict(X, w, threshold):
    return [1 if sigmoid(sum(a * b for a, b in zip(row, w))) >= threshold else 0 for row in X]

def metrics_at(y_true, probs, t):
    pred = [1 if p >= t else 0 for p in probs]
    tp = sum(1 for a, b in zip(y_true, pred) if a == 1 and b == 1)
    fp = sum(1 for a, b in zip(y_true, pred) if a == 0 and b == 1)
    fn = sum(1 for a, b in zip(y_true, pred) if a == 1 and b == 0)
    prec = tp / (tp + fp) if tp + fp else 0
    rec = tp / (tp + fn) if tp + fn else 0
    f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0
    return round(prec, 3), round(rec, 3), round(f1, 3)

