def train(rows, labels):
    model = {}
    for c in sorted(set(labels)):
        rs = [r for r, l in zip(rows, labels) if l == c]
        probs = [(sum(r[j] for r in rs) + 1) / (len(rs) + 2) for j in range(len(rows[0]))]
