def posterior(model, x):
    scores = {}
    for c, (prior, probs) in model.items():
        s = prior
        for xj, p in zip(x, probs):
            s *= p if xj == 1 else 1 - p
        scores[c] = s
    total = sum(scores.values())
    return {c: round(s / total, 4) for c, s in scores.items()}

