import math

def entropy(labels):
    n = len(labels)
    h = 0.0
    for c in set(labels):
        p = labels.count(c) / n
        h -= p * math.log(p, 2)
    return round(h, 4)

def info_gain(parent, left, right):
    n = len(parent)
    w = len(left) / n * entropy(left) + len(right) / n * entropy(right)
    return round(entropy(parent) - w, 4)

