def fit(xs, ys, lr, epochs):
    w, b = 0.0, 0.0
    n = len(xs)
    for _ in range(epochs):
        dw = db = 0.0
        for x, y in zip(xs, ys):
            err = (w * x + b) - y
            dw += err * x
            db += err
        w -= lr * 2 * dw / n
        b -= lr * 2 * db / n
    return round(w, 3), round(b, 3)

