        prior, means, vars_ = model[c]
        s = math.log(prior)
        for v, m, var in zip(x, means, vars_):
            s += -0.5 * math.log(2 * math.pi * var) - (v - m) ** 2 / (2 * var)
        return s
    return max(model, key=score)

