import math

def _n(x, m, v):
    return math.exp(-(x - m) ** 2 / (2 * v)) / math.sqrt(2 * math.pi * v)

def e_step(xs, pi, mu, var):
    r = []
    for x in xs:
        row = [p * _n(x, m, v) for p, m, v in zip(pi, mu, var)]
        s = sum(row)
        r.append([v / s for v in row])
    return r

def m_step(xs, r):
    K, n = len(r[0]), len(xs)
    pi, mu, var = [], [], []
    for k in range(K):
        Nk = sum(row[k] for row in r)
        m = sum(row[k] * x for row, x in zip(r, xs)) / Nk
        v = sum(row[k] * (x - m) ** 2 for row, x in zip(r, xs)) / Nk
        pi.append(Nk / n)
        mu.append(m)
        var.append(v)
    return pi, mu, var

